/**
 * Conversation basics (0.29, Kommunikation & samspel → Samtalets grunder, modules 1101–1107):
 * greeting, asking and answering, agreeing, interrupting, showing interest, not understanding and
 * saying goodbye. Most words are phrases, so the pictures are small scenes with speech bubbles that
 * hold icons (never the words themselves), faces that carry the attitude and a grey reference where
 * a contrast helps.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { HL, T, arm, bolt, cat, cup, flake, heart, note, plane, suitcase, sun } from './people';
import { P as F, type Mood, drop, greyed } from './blindFix';
import { checkIcon, houseIcon } from './labelIcons';

// ── Geometry and figures ─────────────────────────────────────────────
const ground = line('M4 112 L116 112', C.grey2, 2);
/** Head and shoulder positions of a standing figure (figures.ts) at x with height factor h. */
const geo = (x: number, h = 1) => { const s = 0.84 * h, ty = 112 - 49 * s; return { s, hy: ty - 56 * s, hr: 10 * s, sy: ty - 38 * s, sl: x - 13 * s, sr: x + 13 * s }; };
const hnd = (x: number, y: number) => circle(x, y, 3, C.skin, C.ink, 1.2);
/** An arm that starts at the shoulder (side −1 = picture-left, 1 = picture-right) and ends in a hand at (tx, ty). */
const reach = (x: number, h: number, side: -1 | 1, tx: number, ty: number) => { const q = geo(x, h); return all(arm(side < 0 ? q.sl : q.sr, q.sy, tx, ty), hnd(tx, ty)); };
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Build> = {}) => F({ x, top, mood, ...more });
/** Baseball cap on the figure at x (young, casual speaker). */
const cap = (x: number, h = 1, col: string = C.red) => { const q = geo(x, h); const k = q.s; return all(path(`M${x - 10 * k} ${q.hy - 2 * k} C${x - 10 * k} ${q.hy - 15 * k} ${x + 10 * k} ${q.hy - 15 * k} ${x + 10 * k} ${q.hy - 2 * k} Z`, col, C.ink, 1.4), path(`M${x + 6 * k} ${q.hy - 3 * k} L${x + 19 * k} ${q.hy - 1 * k} L${x + 9 * k} ${q.hy - 6 * k} Z`, col, C.ink, 1.2)); };
/** Up-and-down marks beside a head: the person nods. */
const nodM = (x: number, h = 1) => { const q = geo(x, h); return path(`M${x - q.hr - 4} ${q.hy - 6} q-2.6 6 0 12 M${x + q.hr + 4} ${q.hy - 6} q2.6 6 0 12 M${x - q.hr - 8} ${q.hy - 3} q-2 3 0 6 M${x + q.hr + 8} ${q.hy - 3} q2 3 0 6`, 'none', HL, 1.5); };
/** Motion marks beside a raised hand (waving). */
const waveM = (x: number, y: number) => path(`M${x - 7} ${y - 6} q-3 6 0 12 M${x + 7} ${y - 6} q3 6 0 12`, 'none', HL, 1.4);

// ── Speech ───────────────────────────────────────────────────────────
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty); the tail leaves from the side that faces the target. */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white, stroke: string = C.ink) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[], a2: number[], b2: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, inw = tx < L ? 1.6 : -1.6, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; a2 = [e + inw, by - 3.6]; b2 = [e + inw, by + 3.6]; }
  else { const e = ty > cy ? B : Tp, inw = ty > cy ? -1.6 : 1.6, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; a2 = [bx - 4, e + inw]; b2 = [bx + 4, e + inw]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, stroke, 1.5), rect(L, Tp, w, h, fill, 6, stroke, 1.5), path(`M${a2[0]} ${a2[1]} L${tx} ${ty} L${b2[0]} ${b2[1]} Z`, fill, null), inner);
};
/** Bubble beside the head of the figure at x (side 1 = to the right of the head, −1 = to the left); f draws the content at the bubble centre. */
const sb = (x: number, h: number, side: 1 | -1, w: number, hh: number, f: (cx: number, cy: number) => Svg, dx = 0, dy = 0) => { const k = geo(x, h), cx = x + side * (k.hr + 6 + w / 2) + dx, cy = k.hy - 8 + dy; return say(cx, cy, w, hh, x + side * (k.hr + 1), k.hy, f(cx, cy)); };

// ── Icons (about 12 units) ───────────────────────────────────────────
const q = (x: number, y: number, sz = 13, col: string = C.navy) => T(x, y + sz * 0.36, '?', sz, col);
const ex = (x: number, y: number, sz = 13, col: string = HL) => T(x, y + sz * 0.36, '!', sz, col);
const dots = (x: number, y: number, col: string = C.grey) => all(circle(x - 5, y, 1.5, col, null), circle(x, y, 1.5, col, null), circle(x + 5, y, 1.5, col, null));
const face = (x: number, y: number, r: number, m: 'smile' | 'sad' | 'flat' | 'grin' = 'smile', col: string = C.yellow) => all(circle(x, y, r, col, C.ink, 1.1), circle(x - r * 0.36, y - r * 0.22, r * 0.13, C.ink, null), circle(x + r * 0.36, y - r * 0.22, r * 0.13, C.ink, null),
  m === 'flat' ? line(`M${x - r * 0.4} ${y + r * 0.38} L${x + r * 0.4} ${y + r * 0.38}`, C.ink, 1.1)
    : m === 'sad' ? path(`M${x - r * 0.42} ${y + r * 0.55} Q${x} ${y + r * 0.15} ${x + r * 0.42} ${y + r * 0.55}`, 'none', C.ink, 1.1)
      : path(`M${x - r * 0.46} ${y + r * 0.2} Q${x} ${y + r * (m === 'grin' ? 0.85 : 0.68)} ${x + r * 0.46} ${y + r * 0.2}${m === 'grin' ? ' Z' : ''}`, m === 'grin' ? '#c84a4a' : 'none', C.ink, 1.1));
const thumb = (x: number, y: number, s = 1, down = false) => g(`translate(${x} ${y}) scale(${s} ${down ? -s : s})`, rect(-4.4, -11, 4.4, 10, C.skin, 2.2, C.ink, 1.1), rect(-5, -3, 11, 10, C.skin, 3, C.ink, 1.1), line('M-0.6 0.4 L5.4 0.4 M-0.6 3.4 L5.4 3.4', C.ink, 0.8), rect(-8, -2.4, 3.2, 9, C.navy, 1, C.ink, 0.9));
const cross = (x: number, y: number, s = 1, col: string = C.red) => line(`M${x - 5 * s} ${y - 5 * s} L${x + 5 * s} ${y + 5 * s} M${x + 5 * s} ${y - 5 * s} L${x - 5 * s} ${y + 5 * s}`, col, 2.4 * s);
const check = (x: number, y: number, s = 1, col: string = C.green) => checkIcon(x, y, s, col);
const palm = (x: number, y: number, s = 1, marks = true) => g(`translate(${x} ${y}) scale(${s})`, ...[-4.6, -1.6, 1.4, 4.4].map((d, i) => rect(d - 1.3, -9 + Math.abs(i - 1.5) * 1.2, 2.6, 9, C.skin, 1.3, C.ink, 0.9)), path('M-5.5 -1 L5.5 -1 L5 5 C4 8 -4 8 -5 5 Z', C.skin, C.ink, 1), path('M-5.4 1 L-9 -3 C-10 -4 -11 -2 -10 -1 L-5 5', C.skin, C.ink, 1), marks ? path('M-12 -8 q-3 5 0 10 M12 -8 q3 5 0 10', 'none', HL, 1.2) : '');
const flagJP = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -6, 18, 12, C.white, 1, C.ink, 1), circle(0, 0, 3.4, '#d6302c', null));
const flagSE = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -6, 18, 12, '#2f6ab8', 1, C.ink, 1), rect(-4.5, -6, 3, 12, '#f2c94e', 0, null), rect(-9, -1.5, 18, 3, '#f2c94e', 0, null));
const cal = (x: number, y: number, s = 1, mark = -1, cols = 4) => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -9, 20, 18, C.white, 2, C.ink, 1.2), rect(-10, -9, 20, 5, C.red, 2, C.ink, 1.2), ...Array.from({ length: cols * 2 }, (_, i) => { const cx = -7 + (i % cols) * (14 / (cols - 1)), cy = 0 + Math.floor(i / cols) * 5; return i === mark ? circle(cx, cy, 2.2, HL, null) : circle(cx, cy, 1, C.grey, null); }));
const clock = (x: number, y: number, r = 8, hAng = 300, mAng = 0, fill: string = C.white) => { const p = (a: number, l: number) => `${(x + Math.sin((a * Math.PI) / 180) * l).toFixed(1)} ${(y - Math.cos((a * Math.PI) / 180) * l).toFixed(1)}`; return all(circle(x, y, r, fill, C.ink, 1.4), line(`M${x} ${y} L${p(hAng, r * 0.5)} M${x} ${y} L${p(mAng, r * 0.78)}`, C.ink, 1.3)); };
const iceCream = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-5 -1 L5 -1 L0 11 Z', C.tan, C.ink, 1), line('M-3 2 L2 6 M2 1 L-1 6', '#a0673d', 0.7), circle(0, -4, 5.4, C.pink, C.ink, 1));
const pen = (x: number, y: number, s = 1, rot = -35) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-2, -10, 4, 16, C.navy, 1, C.ink, 1), path('M-2 6 L2 6 L0 10 Z', C.beige, C.ink, 0.9));
const ball = (x: number, y: number, r = 6) => all(circle(x, y, r, C.white, C.ink, 1.2), path(`M${x} ${y - r * 0.4} L${x + r * 0.38} ${y - r * 0.1} L${x + r * 0.24} ${y + r * 0.34} L${x - r * 0.24} ${y + r * 0.34} L${x - r * 0.38} ${y - r * 0.1} Z`, C.ink, null));
const bus = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-11, -7, 22, 13, C.red, 2.4, C.ink, 1.2), rect(-9, -5, 6, 5, '#bfe3f5', 1, null), rect(-1.5, -5, 6, 5, '#bfe3f5', 1, null), circle(-6, 6.5, 2.2, C.dark, null), circle(6, 6.5, 2.2, C.dark, null));
const walker = (x: number, y: number, s = 1, col: string = C.navy) => g(`translate(${x} ${y}) scale(${s})`, circle(1, -8, 2.4, col, null), line('M1 -5 L0 2 M0 2 L-3 8 M0 2 L3 8 M0.6 -3 L-3 0 M0.6 -3 L4 -1', col, 1.8));
const glassW = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-4 -8 L4 -8 C4 -2 2 -1 0 -1 C-2 -1 -4 -2 -4 -8 Z', 'rgba(220,60,80,0.7)', C.ink, 1), line('M0 -1 L0 6 M-3 6 L3 6', C.ink, 1.1));
const mic = (x: number, y: number, s = 1, rot = 0) => g(`translate(${x} ${y}) rotate(${rot}) scale(${s})`, rect(-1.8, 0, 3.6, 12, C.dark, 1.4, C.ink, 1), circle(0, -2, 4.4, C.grey, C.ink, 1.1), line('M-3 -3 L3 -3 M-3 -1 L3 -1', C.dark, 0.6));
const glass = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, circle(0, 0, 5, 'rgba(220,240,252,0.7)', C.ink, 1.4), line('M3.6 3.6 L8 8', C.ink, 2));
const umbrella = (x: number, y: number, s = 1, col: string = C.purple) => g(`translate(${x} ${y}) scale(${s})`, path('M-12 0 C-12 -12 12 -12 12 0 C9 -2 7 -2 4 0 C1 -2 -1 -2 -4 0 C-7 -2 -9 -2 -12 0 Z', col, C.ink, 1.2), line('M0 0 L0 12 C0 15 -4 15 -4 12', C.ink, 1.4));
const scribble = (x: number, y: number, w: number, col: string = C.grey) => path(`M${x - w / 2} ${y} c3 -6 6 6 9 0 s4 -7 8 1 s3 6 7 -2 s5 -4 6 3 s-5 5 -10 -3 s-6 -2 -9 4`, 'none', col, 1.4);
const lines = (x: number, y: number, w: number, n = 3, col: string = C.grey) => all(...Array.from({ length: n }, (_, i) => line(`M${x - w / 2} ${y + i * 4.4} L${x + w / 2 - (i === n - 1 ? w * 0.35 : 0)} ${y + i * 4.4}`, col, 1.6)));
const brief = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-9, -5, 18, 13, '#8a5a3a', 2, C.ink, 1.2), path('M-3 -5 L-3 -8 L3 -8 L3 -5', 'none', C.ink, 1.2), line('M-9 0 L9 0', '#5a3a2a', 1));
const puzzle = (x: number, y: number, s = 1, col: string = C.sky) => g(`translate(${x} ${y}) scale(${s})`, path('M-8 -8 L-2 -8 C-2 -12 3 -12 3 -8 L8 -8 L8 -2 C12 -2 12 3 8 3 L8 8 L-8 8 Z', col, C.ink, 1.2));
const zz = (x: number, y: number) => all(T(x, y, 'z', 8, C.navy), T(x + 6, y - 5, 'z', 10, C.navy), T(x + 13, y - 11, 'z', 12, C.navy));
const pin = (x: number, y: number, s = 1, col: string = HL) => g(`translate(${x} ${y}) scale(${s})`, path('M0 8 C-6 0 -6 -8 0 -8 C6 -8 6 0 0 8 Z', col, C.ink, 1.1), circle(0, -3, 2, C.white, null));
const idea = (x: number, y: number, s = 1, lit = true) => g(`translate(${x} ${y}) scale(${s})`, lit ? path('M-9 -9 l-3 -3 M0 -12 l0 -4 M9 -9 l3 -3', 'none', C.gold, 1.6) : '', circle(0, -2, 6, lit ? C.yellow : C.grey2, C.ink, 1.2), rect(-3, 3.5, 6, 4.5, C.grey, 1, C.ink, 1));
const chain = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-11, -4, 12, 8, 'none', 4, C.ink, 2.2), rect(-1, -4, 12, 8, 'none', 4, HL, 2.2));
const cake = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, rect(-8, -3, 16, 9, '#f6c0d0', 1.5, C.ink, 1.1), rect(-8, -6, 16, 4, C.white, 1.5, C.ink, 1.1), circle(0, -8, 2, C.red, null));
const pizza = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M0 8 L-8 -6 C-3 -9 3 -9 8 -6 Z', '#f2c14e', C.ink, 1.1), path('M-8 -6 C-3 -9 3 -9 8 -6', 'none', '#c8925a', 2.2), circle(-2, -3, 1.6, C.red, null), circle(2, 1, 1.4, C.red, null));
const plate2 = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, circle(0, 0, 7, C.white, C.ink, 1.1), circle(0, 0, 4, 'none', C.grey2, 1), line('M-11 -6 L-11 6 M-12.5 -6 L-12.5 -2 M-9.5 -6 L-9.5 -2 M11 6 L11 -6 C13 -4 13 0 11 0', C.ink, 1));
